#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <new>
#include <string>
#include <utility>

// Count live heap allocations so leaks and double frees are visible.
static long g_live = 0;

void* operator new(std::size_t n)
{
    void* p = std::malloc(n ? n : 1);
    if (!p) { throw std::bad_alloc(); }
    g_live++;
    return p;
}
void* operator new[](std::size_t n) { return operator new(n); }
void operator delete(void* p) noexcept { if (p) { g_live--; std::free(p); } }
void operator delete[](void* p) noexcept { operator delete(p); }
void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
void operator delete[](void* p, std::size_t) noexcept { operator delete(p); }

// The solution defines Text's members; this declaration must match its.
class Text
{
public:
    Text(const char* s);
    Text(const Text& other);
    Text(Text&& other) noexcept;
    Text& operator=(const Text& other);
    Text& operator=(Text&& other) noexcept;
    ~Text();

    const char* c_str() const;
    std::size_t size() const;
    void set_char(std::size_t i, char c);

private:
    char* data_;
    std::size_t size_;
};

static void show(const char* label, const Text& t)
{
    std::cout << label << "=[" << t.c_str() << "] size=" << t.size() << "\n";
}

static void scenario(const std::string& word)
{
    Text a(word.c_str());

    Text b(a);                        // copy constructor
    if (b.size() > 0) { b.set_char(0, '#'); }
    show("a", a);
    show("b", b);

    Text c("xx");
    c = a;                            // copy assignment over a live value
    if (c.size() > 0) { c.set_char(0, '@'); }
    show("a", a);
    show("c", c);

    Text& self = a;
    a = self;                         // self-assignment
    show("a", a);

    Text d(std::move(a));             // move constructor
    show("d", d);
    show("a", a);

    Text e("zz");
    e = std::move(d);                 // move assignment over a live value
    show("e", e);
    show("d", d);
}

int main()
{
    std::string line;
    std::cout << "" << std::flush;    // let iostream finish any lazy setup
    while (std::getline(std::cin, line))
    {
        long before = g_live;
        scenario(line);
        std::cout << "live=" << (g_live - before) << "\n";
    }
    return 0;
}

