"""Random short words, including the empty string."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 8)
    word = "".join(rng.choice("abcdefgh") for _ in range(n))
    return {"name": "a text of %d characters #%d" % (n, index),
            "stdin": word + "\n"}
